from itertools import permutations

class Solution:
    def isPrintable(self, targetGrid: List[List[int]]) -> bool:
        m, n = len(targetGrid), len(targetGrid[0])
        colors = sorted({v for row in targetGrid for v in row})
        boxes = {c: [m, n, -1, -1] for c in colors}
        for r in range(m):
            for c in range(n):
                b = boxes[targetGrid[r][c]]
                b[0], b[2] = min(b[0], r), max(b[2], r)
                b[1], b[3] = min(b[1], c), max(b[3], c)
        for perm in permutations(colors):
            g = [[0] * n for _ in range(m)]
            for col in perm:
                top, left, bottom, right = boxes[col]
                for r in range(top, bottom + 1):
                    for c in range(left, right + 1):
                        g[r][c] = col
            if g == targetGrid:
                return True
        return False

