class Solution {
public:
    bool isPrintable(vector<vector<int>>& targetGrid) {
        int m = targetGrid.size(), n = targetGrid[0].size();
        vector<int> cols;
        map<int, array<int, 4>> boxes;
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++) {
                int col = targetGrid[r][c];
                if (!boxes.count(col)) {
                    boxes[col] = {m, n, -1, -1};
                    cols.push_back(col);
                }
                auto& b = boxes[col];
                b[0] = min(b[0], r); b[2] = max(b[2], r);
                b[1] = min(b[1], c); b[3] = max(b[3], c);
            }
        sort(cols.begin(), cols.end());
        do {
            vector<vector<int>> g(m, vector<int>(n, 0));
            for (int col : cols) {
                auto& b = boxes[col];
                for (int r = b[0]; r <= b[2]; r++)
                    for (int c = b[1]; c <= b[3]; c++)
                        g[r][c] = col;
            }
            if (g == targetGrid) return true;
        } while (next_permutation(cols.begin(), cols.end()));
        return false;
    }
};

