class Solution {
    public boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length, n = targetGrid[0].length;
        TreeSet<Integer> set = new TreeSet<>();
        Map<Integer, int[]> boxes = new HashMap<>();
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++) {
                int col = targetGrid[r][c];
                set.add(col);
                int[] b = boxes.get(col);
                if (b == null) boxes.put(col, new int[]{m, n, -1, -1});
                b = boxes.get(col);
                b[0] = Math.min(b[0], r); b[2] = Math.max(b[2], r);
                b[1] = Math.min(b[1], c); b[3] = Math.max(b[3], c);
            }
        List<Integer> cols = new ArrayList<>(set);
        return permute(cols, 0, boxes, targetGrid, m, n);
    }

    private boolean permute(List<Integer> cols, int i, Map<Integer, int[]> boxes,
                            int[][] target, int m, int n) {
        if (i == cols.size()) {
            int[][] g = new int[m][n];
            for (int col : cols) {
                int[] b = boxes.get(col);
                for (int r = b[0]; r <= b[2]; r++)
                    for (int c = b[1]; c <= b[3]; c++)
                        g[r][c] = col;
            }
            return Arrays.deepEquals(g, target);
        }
        for (int j = i; j < cols.size(); j++) {
            Collections.swap(cols, i, j);
            if (permute(cols, i + 1, boxes, target, m, n)) return true;
            Collections.swap(cols, i, j);
        }
        return false;
    }
}

