            b[1] = Math.min(b[1], c); b[3] = Math.max(b[3], c);
        }
    const permute = (arr, i) => {
        if (i === arr.length) {
            const g = Array.from({ length: m }, () => new Array(n).fill(0));
            for (const col of arr) {
                const [top, left, bottom, right] = boxes.get(col);
                for (let r = top; r <= bottom; r++)
                    for (let c = left; c <= right; c++) g[r][c] = col;
