        for (let j = i; j < arr.length; j++) {
            [arr[i], arr[j]] = [arr[j], arr[i]];
            if (permute(arr, i + 1)) return true;
            [arr[i], arr[j]] = [arr[j], arr[i]];
        }
        return false;
    };
    return permute(colors, 0);
};

