class Solution:
    def isPrintable(self, targetGrid: List[List[int]]) -> bool:
        m, n = len(targetGrid), len(targetGrid[0])
        boxes = {}
        for r in range(m):
            for c in range(n):
                col = targetGrid[r][c]
                if col not in boxes:
                    boxes[col] = [r, r, c, c]
                else:
                    b = boxes[col]
                    b[0], b[1], b[2], b[3] = (min(b[0], r), max(b[1], r),
                                              min(b[2], c), max(b[3], c))
        adj = {col: set() for col in boxes}
        indeg = {col: 0 for col in boxes}
        for col, (top, bottom, left, right) in boxes.items():
            inner = set()
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    inner.add(targetGrid[r][c])
            for d in inner:
                if d != col and d not in adj[col]:
                    adj[col].add(d)
                    indeg[d] += 1
        stack = [col for col, dg in indeg.items() if dg == 0]
        done = 0
        while stack:
            col = stack.pop()
            done += 1
            for d in adj[col]:
                indeg[d] -= 1
                if indeg[d] == 0:
                    stack.append(d)
        return done == len(boxes)

