class Solution {
public:
    bool isPrintable(vector<vector<int>>& targetGrid) {
        int m = targetGrid.size(), n = targetGrid[0].size();
        unordered_map<int, array<int, 4>> boxes;
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++) {
                int col = targetGrid[r][c];
                auto it = boxes.find(col);
                if (it == boxes.end()) boxes[col] = {r, r, c, c};
                else {
                    auto& b = it->second;
                    b[0] = min(b[0], r); b[1] = max(b[1], r);
                    b[2] = min(b[2], c); b[3] = max(b[3], c);
                }
            }
        unordered_map<int, unordered_set<int>> adj;
        unordered_map<int, int> indeg;
        for (auto& [col, b] : boxes) indeg[col] = 0;
        for (auto& [col, b] : boxes) {
            unordered_set<int> inner;
            for (int r = b[0]; r <= b[1]; r++)
                for (int c = b[2]; c <= b[3]; c++)
                    inner.insert(targetGrid[r][c]);
            for (int d : inner)
                if (d != col && adj[col].insert(d).second) indeg[d]++;
        }
        vector<int> st;
        for (auto& [col, dg] : indeg) if (dg == 0) st.push_back(col);
        int done = 0, total = indeg.size();
        while (!st.empty()) {
            int col = st.back(); st.pop_back();
            done++;
            for (int d : adj[col])
                if (--indeg[d] == 0) st.push_back(d);
        }
        return done == total;
    }
};

