class Solution {
    public boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length, n = targetGrid[0].length;
        Map<Integer, int[]> boxes = new HashMap<>();
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++) {
                int col = targetGrid[r][c];
                int[] b = boxes.get(col);
                if (b == null) boxes.put(col, new int[]{r, r, c, c});
                else {
                    b[0] = Math.min(b[0], r); b[1] = Math.max(b[1], r);
                    b[2] = Math.min(b[2], c); b[3] = Math.max(b[3], c);
                }
            }
        Map<Integer, Set<Integer>> adj = new HashMap<>();
        Map<Integer, Integer> indeg = new HashMap<>();
        for (int col : boxes.keySet()) {
            adj.put(col, new HashSet<>());
            indeg.put(col, 0);
        }
        for (Map.Entry<Integer, int[]> e : boxes.entrySet()) {
            int col = e.getKey();
            int[] b = e.getValue();
            Set<Integer> inner = new HashSet<>();
            for (int r = b[0]; r <= b[1]; r++)
                for (int c = b[2]; c <= b[3]; c++)
                    inner.add(targetGrid[r][c]);
            for (int d : inner)
                if (d != col && adj.get(col).add(d)) indeg.merge(d, 1, Integer::sum);
        }
        Deque<Integer> st = new ArrayDeque<>();
        for (Map.Entry<Integer, Integer> e : indeg.entrySet())
            if (e.getValue() == 0) st.push(e.getKey());
        int done = 0;
        while (!st.isEmpty()) {
            int col = st.pop();
            done++;
            for (int d : adj.get(col))
                if (indeg.merge(d, -1, Integer::sum) == 0) st.push(d);
        }
        return done == indeg.size();
    }
}

