    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++) {
            const col = targetGrid[r][c];
            const b = boxes.get(col);
            if (!b) boxes.set(col, [r, r, c, c]);
            else {
                b[0] = Math.min(b[0], r); b[1] = Math.max(b[1], r);
                b[2] = Math.min(b[2], c); b[3] = Math.max(b[3], c);
            }
        }
    const adj = new Map(), indeg = new Map();
    for (const col of boxes.keys()) {
        adj.set(col, new Set());
        indeg.set(col, 0);
    }
    for (const [col, b] of boxes) {
        const inner = new Set();
        for (let r = b[0]; r <= b[1]; r++)
            for (let c = b[2]; c <= b[3]; c++)
                inner.add(targetGrid[r][c]);
        for (const d of inner)
            if (d !== col && !adj.get(col).has(d)) {
                adj.get(col).add(d);
                indeg.set(d, indeg.get(d) + 1);
            }
    }
    const st = [];
    for (const [col, dg] of indeg) if (dg === 0) st.push(col);
    let done = 0;
    while (st.length) {
        const col = st.pop();
        done++;
        for (const d of adj.get(col)) {
            indeg.set(d, indeg.get(d) - 1);
            if (indeg.get(d) === 0) st.push(d);
        }
    }
    return done === indeg.size;
};
